# -*- coding: utf-8 -*-
"""SBOM 生成器（tools/gen_sbom.py，issue #206）的解析与结构测试。

钉三件事：① 两个锁文件的解析对假数据与**真实仓库数据**都成立；② SPDX 结构
必需字段齐全、SPDXID 全文档唯一（重名不处理会产出非法文档，下游导入即失败）；
③ 空解析是硬失败——零包 SBOM 比不产出更糟（验收会假绿）。
"""

import io
import json
import os
import sys

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT_DIR, "tools"))

import gen_sbom  # noqa: E402


def test_parse_requirements_lock_skips_hashes_and_comments():
    text = (
        "# autogenerated\n"
        "altgraph==0.17.5 \\\n"
        "    --hash=sha256:aaa \\\n"
        "    --hash=sha256:bbb\n"
        "    # via pyinstaller\n"
        "\n"
        "annotated-doc==0.0.5 \\\n"
        "    --hash=sha256:ccc\n"
    )
    assert gen_sbom.parse_requirements_lock(text) == [
        ("altgraph", "0.17.5"), ("annotated-doc", "0.0.5")]


def test_parse_package_lock_reads_nested_and_scoped():
    data = {"packages": {
        "": {"name": "frontend", "version": "0.1.0"},          # 根条目：跳过
        "node_modules/react": {"version": "19.3.0"},
        "node_modules/@scope/pkg": {"version": "1.2.3"},       # scoped 保留整名
        "node_modules/a/node_modules/b": {"name": "b", "version": "2.0.0"},
    }}
    assert sorted(gen_sbom.parse_package_lock(data)) == [
        ("@scope/pkg", "1.2.3"), ("b", "2.0.0"), ("react", "19.3.0")]


def test_spdx_ids_unique_for_multi_version_same_name():
    """同名多版本（npm 嵌套安装的常态）必须产出互不相同的 SPDXID。"""
    pkgs = gen_sbom._spdx_packages(
        "npm", [("foo", "1.0.0"), ("foo", "2.0.0"), ("bar", "1.0.0")])
    ids = [p["SPDXID"] for p in pkgs]
    assert len(ids) == len(set(ids))
    assert all(p["SPDXID"].startswith("SPDXRef-Package-npm-") for p in pkgs)


def test_build_spdx_required_fields():
    doc = gen_sbom.build_spdx([("fastapi", "0.141.0")], [("react", "19.3.0")],
                              "26.10.0", "2026-10-03T00:00:00Z")
    assert doc["spdxVersion"] == "SPDX-2.3"
    assert doc["dataLicense"] == "CC0-1.0"
    assert doc["SPDXID"] == "SPDXRef-DOCUMENT"
    assert doc["name"] == "job-workbench-26.10.0"
    assert doc["creationInfo"]["created"] == "2026-10-03T00:00:00Z"
    assert {p["name"] for p in doc["packages"]} == {"fastapi", "react"}
    ids = [p["SPDXID"] for p in doc["packages"]]
    assert len(ids) == len(set(ids))


def test_real_repo_lockfiles_parse(tmp_path):
    """对**真实仓库**的锁文件跑一遍：端到端产出可解析、双链齐全的 JSON。"""
    out = tmp_path / "sbom.spdx.json"
    code = gen_sbom.main(["--root", ROOT_DIR, "--version", "26.10.0",
                          "--out", str(out)])
    assert code == 0
    doc = json.loads(io.open(str(out), encoding="utf-8").read())
    assert len(doc["packages"]) >= 100        # 实测 22 python + 513 npm
    kinds = {p["SPDXID"].split("-")[2] for p in doc["packages"]}
    assert kinds == {"python", "npm"}


def test_empty_parse_is_hard_failure(tmp_path, capsys):
    """锁文件在但解析为空 → 退出码 1（零包 SBOM 不许静默产出）。"""
    root = tmp_path / "repo"
    (root / "web" / "backend").mkdir(parents=True)
    (root / "web" / "frontend").mkdir(parents=True)
    (root / "web" / "backend" / "requirements.lock").write_text(
        "# 只剩注释\n", encoding="utf-8")
    (root / "web" / "frontend" / "package-lock.json").write_text(
        '{"packages": {}}', encoding="utf-8")

    code = gen_sbom.main(["--root", str(root), "--version", "1.0.0",
                          "--out", str(tmp_path / "x.json")])
    assert code == 1
    assert "空" in capsys.readouterr().err
